1: /** Platform-neutral serial coordination. No command execution, network or persistence.
2:  * Registry and host attestations are trusted inputs, never imported from Task Context.
3:  */
4: import { createHash, randomUUID } from 'node:crypto';
5: import { lstatSync, readFileSync, readdirSync, realpathSync } from 'node:fs';
6: import path from 'node:path';
7: 
8: export const digest = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
9: export const operationBinding = host => digest(host.requests ?? {});
10: export const taskBinding = task => digest({ id: task.id, goal: task.goal, acceptance: task.acceptance, decisions: task.decisions });
11: const copy = value => JSON.parse(JSON.stringify(value));
12: const assert = (ok, message) => { if (!ok) throw new Error(message); };
13: const recovered = new WeakMap();
14: const runtimeTasks = new WeakSet();
15: const states = new Set(['pending', 'running', 'completed', 'reused', 'skipped', 'evidence_insufficient', 'permission_blocked', 'validation_failed', 'interrupted']);
16: const allowedCapabilities = ['read_files', 'write_files', 'run_shell_commands', 'access_network', 'destructive_actions_allowed'];
17: const safePath = p => typeof p === 'string' && p !== '' && !path.isAbsolute(p) && !p.split(/[\\/]/).includes('..');
18: 
19: function checkPath(root, relative) {
20:   assert(safePath(relative), 'Dependency path must be repository-relative');
21:   let current = realpathSync(root);
22:   for (const part of relative.split(/[\\/]/)) {
23:     current = path.join(current, part);
24:     try { assert(!lstatSync(current).isSymbolicLink(), 'Symlink paths require host inspection'); }
25:     catch (error) { if (error.code !== 'ENOENT') throw error; }
26:   }
27:   return current;
28: }
29: 
30: // Include directory membership (new/deleted files), executable bits and file bytes.
31: // Never follow symlinks or read outside the explicitly supplied repository root.
32: export function fingerprint(root, relative) {
33:   const current = checkPath(root, relative);
34:   try { lstatSync(current); } catch (error) { if (error.code === 'ENOENT') return 'missing'; throw error; }
35:   function visit(file) {
36:     const stat = lstatSync(file);
37:     assert(!stat.isSymbolicLink(), 'Symlink dependencies require host inspection');
38:     if (stat.isDirectory()) return readdirSync(file).sort().map(name => [name, visit(path.join(file, name))]);
39:     assert(stat.isFile(), 'Only regular files/directories can be fingerprinted');
40:     return [stat.mode & 0o111, createHash('sha256').update(readFileSync(file)).digest('hex')];
41:   }
42:   return digest(visit(current));
43: }
44: 
45: export function captureEvidence(root, input, environment) {
46:   assert(input.id && input.source && input.summary, 'Evidence needs id, source and summary');
47:   assert(Array.isArray(input.dependencies) && input.dependencies.length, 'Evidence needs dependency coverage');
48:   const bindings = Object.fromEntries(input.dependencies.map(p => [p, fingerprint(root, p)]));
49:   return { ...copy(input), bindings, environment: copy(environment), recorded_at: new Date().toISOString() };
50: }
51: 
52: export function evidenceValidity(evidence, host) {
53:   if (!evidence || !host.trustedEvidence?.has(digest(evidence))) return { status: 'unknown', reason: 'source_not_attested' };
54:   if (!['pass', 'fail'].includes(evidence.result)) return { status: 'unknown', reason: 'result_not_observed' };
55:   if (evidence.coverage_complete !== true || !evidence.bindings || !Object.keys(evidence.bindings).length
56:       || !evidence.environment || !Object.keys(evidence.environment).length) {
57:     return { status: 'unknown', reason: 'dependency_or_environment_coverage_unknown' };
58:   }
59:   if (evidence.kind === 'test' && (!evidence.command || !evidence.cwd || !Number.isInteger(evidence.exit_code) || (evidence.result === 'pass' ? evidence.exit_code !== 0 : evidence.exit_code === 0))) {
60:     return { status: 'unknown', reason: 'execution_receipt_missing' };
61:   }
62:   if (evidence.kind === 'signal' && (!evidence.command || !evidence.cwd || !Number.isInteger(evidence.exit_code)
63:       || evidence.observed_target_failure !== true || !evidence.success_criterion || !evidence.failure_criterion)) {
64:     return { status: 'unknown', reason: 'reliable_failure_signal_missing' };
65:   }
66:   let unknownReason = null;
67:   for (const [key, value] of Object.entries(evidence.environment)) {
68:     if (!(key in (host.environment ?? {}))) { unknownReason ??= `environment_unknown:${key}`; continue; }
69:     if (host.environment[key] !== value) return { status: 'stale', reason: `environment_changed:${key}` };
70:   }
71:   for (const [file, hash] of Object.entries(evidence.bindings)) {
72:     try {
73:       if (fingerprint(host.root, file) !== hash) return { status: 'stale', reason: `dependency_changed:${file}` };
74:     } catch (error) { unknownReason ??= error.message; }
75:   }
76:   if (unknownReason) return { status: 'unknown', reason: unknownReason };
77:   return evidence.result === 'pass' ? { status: 'valid', reason: 'attested_inputs_unchanged' } : { status: 'failed', reason: 'observed_failure' };
78: }
79: 
80: export function validationPlan(evidence, host) {
81:   return evidence.map(item => ({ id: item.id, ...evidenceValidity(item, host) }))
82:     .map(item => ({ ...item, action: item.status === 'valid' ? 'reuse' : item.status === 'unknown' ? 'investigate' : 'rerun' }));
83: }
84: 
85: export function reviewBinding(root, task, baseline, files) {
86:   assert(baseline && Array.isArray(files) && files.length, 'Review needs a baseline and complete changed/related paths');
87:   return digest({ baseline, goal: task.goal, acceptance: task.acceptance, decisions: task.decisions,
88:     files: [...new Set(files)].sort().map(file => [file, fingerprint(root, file)]) });
89: }
