91: function definition(task, registry, inventory) {
92:   assert(runtimeTasks.has(task), 'Untrusted Task Context: use createTask or restoreTask');
93:   assert(task.registry_binding === digest(registry), 'Registry changed; explicitly migrate/reselect workflow');
94:   if (task.workflow_id) {
95:     const workflow = registry.workflows[task.workflow_id];
96:     assert(workflow, 'Unknown registered workflow');
97:     return workflow;
98:   }
99:   assert(inventory.has(task.skill_id), 'Unknown single Skill');
100:   return { stages: [{ id: 'task', type: 'skill', skill: task.skill_id, optional: false, condition: 'always', prerequisites: [], next: [], permission: 'request_scoped', stop_conditions: [] }], stop_conditions: [] };
101: }
102: 
103: export function createTask({ id, goal, acceptance, workflow_id = null, skill_id = null }, registry, inventory) {
104:   assert(id && goal && Array.isArray(acceptance) && acceptance.length, 'Goal and acceptance are required');
105:   assert(acceptance.every(item => typeof item === 'string' && item.length) && new Set(acceptance).size === acceptance.length, 'Acceptance IDs must be distinct strings');
106:   assert(Boolean(workflow_id) !== Boolean(skill_id), 'Choose one registered workflow or one existing Skill');
107:   const task = { schema_version: 2, id, goal, acceptance: copy(acceptance), workflow_id, skill_id,
108:     registry_binding: digest(registry), decisions: [], scope: { files: [], modules: [], interfaces: [] },
109:     risks: [], permission_refs: [], evidence: [], changes: [], unresolved: [], next_actions: [],
110:     current_stage: null, steps: {}, history: [] };
111:   runtimeTasks.add(task);
112:   for (const stage of definition(task, registry, inventory).stages) task.steps[stage.id] = { status: 'pending', attempts: 0, evidence_ids: [] };
113:   return task;
114: }
115: 
116: function evidenceFor(task, ids, host) {
117:   return ids?.length > 0 && ids.every(id => {
118:     const evidence = task.evidence.find(e => e.id === id);
119:     return evidence?.task_binding === taskBinding(task) && evidenceValidity(evidence, host).status === 'valid';
120:   });
121: }
122: function condition(task, name, host) {
123:   if (name === 'always') return true;
124:   const fact = host.conditions?.[name];
125:   return fact && typeof fact.value === 'boolean' && fact.reason && evidenceFor(task, fact.evidence_ids, host) ? fact.value : undefined;
126: }
127: function permission(skill, stage, task, host) {
128:   const metadata = host.inventory.get(skill);
129:   if (!metadata || !['draft', 'beta', 'stable'].includes(metadata.status)) return 'skill_unavailable';
130:   const request = host.requests?.[stage.id];
131:   if (!request) return 'operation_scope_missing';
132:   if (!Array.isArray(request.capabilities) || !request.capabilities.length) return 'capabilities_missing';
133:   if (stage.permission === 'write_scoped' && !request.capabilities.includes('write_files')) return 'write_scope_missing';
134:   if (stage.permission === 'read_only' && request.capabilities.includes('write_files')) return 'read_only_stage';
135:   for (const capability of request.capabilities) {
136:     if (!allowedCapabilities.includes(capability) || metadata.permissions?.[capability] !== true
137:         || host.capabilities?.[capability] !== true) return `capability_denied:${capability}`;
138:     const grants = host.grants?.filter(g => g.task_id === task.id && g.capability === capability && g.source
139:       && g.skills.includes(skill)) ?? [];
140:     if (!grants.length) return `user_authorization_missing:${capability}`;
141:     if (['read_files', 'write_files'].includes(capability)) {
142:       if (!request.paths?.length || request.paths.some(p => !safePath(p))) return 'explicit_paths_missing';
143:       if (request.paths.some(p => !grants.some(g => g.paths?.includes(p)))) return `path_not_authorized:${capability}`;
144:       try { for (const p of request.paths) checkPath(host.root, p); } catch { return 'unsafe_path'; }
145:     } else if (!request.operation || !grants.some(g => g.operations?.includes(request.operation))) return `operation_not_authorized:${capability}`;
146:   }
147:   const check = host.skillChecks?.[stage.id];
148:   if (!check?.source || check.request_binding !== digest(request) || check.skill_binding !== digest(metadata) || check.allowed !== true) return 'skill_scope_not_verified';
149:   if (request.capabilities.includes('run_shell_commands') && request.preflight !== 'safe') return 'command_preflight_missing';
150:   return null;
151: }
152: 
153: function potentiallyEffectful(stage, host) {
154:   return host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files') || stage.permission === 'write_scoped';
155: }
156: 
157: function writes(stage, host) {
158:   return stage.permission === 'write_scoped' || (stage.permission === 'request_scoped' && host.requests?.[stage.id]?.capabilities?.includes('write_files'));
159: }
160: 
161: export function reconciliationBinding(task, stageId, host) {
162:   return digest({ intent: taskBinding(task), stage: stageId, step: task.steps[stageId], request: host.requests?.[stageId] });
163: }
164: 
165: export function recoveryBinding(task, host) {
166:   const checkpoint = recovered.get(task);
167:   return checkpoint ? digest({ checkpoint, intent: taskBinding(task), requests: host.requests, skillChecks: host.skillChecks }) : null;
168: }
169: 
170: function requirement(task, requirement, host) {
171:   return task.evidence.some(e => e.claims?.includes(requirement.claim)
172:     && e.task_binding === taskBinding(task) && e.operation_binding === operationBinding(host)
173:     && (!requirement.skill || e.skill === requirement.skill)
174:     && (!requirement.kind || e.kind === requirement.kind)
175:     && (requirement.kind !== 'review' || (e.kind === 'review' && e.independent === true && host.reviewBinding && e.review_basis === host.reviewBinding))
176:     && evidenceValidity(e, host).status === 'valid');
177: }
178: 
179: function stepEvidence(task, stage, host, executionAttempt = null) {
180:   const step = task.steps[stage.id];
181:   if (!evidenceFor(task, step.evidence_ids, host)) return false;
182:   const evidence = step.evidence_ids.map(id => task.evidence.find(e => e.id === id));
183:   const scoped = evidence.filter(e => e.skill === stage.skill && e.request_binding === digest(host.requests[stage.id]) && e.claims?.includes(`stage:${stage.id}`)
184:     && (executionAttempt === null || e.execution_attempt === executionAttempt));
185:   if (!scoped.length) return false;
186:   if (stage.skill === 'safe-code-review' && !scoped.some(e => e.kind === 'review' && e.independent === true
187:       && e.review_basis && e.review_basis === host.reviewBinding)) return false;
188:   if (stage.skill === 'bug-root-cause-analysis' && !scoped.some(e => e.signal_ids?.length
189:       && e.signal_ids.every(id => task.evidence.some(signal => signal.id === id && signal.kind === 'signal' && signal.task_binding === taskBinding(task)
190:         && evidenceValidity(signal, host).status === 'valid')))) return false;
191:   return true;
192: }
193: 
194: function unresolvedFailures(task, host) {
195:   const unresolved = [];
196:   for (const failed of task.evidence.filter(e => e.kind === 'test' && e.result === 'fail')) {
197:     const validity = evidenceValidity(failed, host);
198:     if (validity.status === 'stale' || validity.reason === 'source_not_attested') continue;
199:     if (validity.status === 'unknown') {
200:       unresolved.push(failed);
201:       continue;
202:     }
203:     const resolution = host.failureResolutions?.get(digest(failed));
204:     const replacement = resolution?.source && task.evidence.find(e => e.id === resolution.replacement);
205:     const identity = e => digest({ command: e.command, cwd: e.cwd, bindings: e.bindings, environment: e.environment });
206:     if (!replacement || replacement.task_binding !== taskBinding(task) || replacement.kind !== 'test'
207:         || evidenceValidity(replacement, host).status !== 'valid' || identity(replacement) !== identity(failed)
208:         || !(Date.parse(replacement.recorded_at) > Date.parse(failed.recorded_at))) {
209:       unresolved.push(failed);
210:     }
211:   }
212:   return unresolved;
213: }
