215: /** Recompute a decision every time. No imported context field grants execution authority. */
216: export function nextAction(task, host) {
217:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
218:   const workflow = definition(task, host.registry, host.inventory);
219:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
220:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };

221:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
222:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
223:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
224:   const recovery = recoveryBinding(task, host);
225:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
226:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
227:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
228:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
229:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
230:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
231:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
232:   const completed = new Set();
233:   for (const stage of workflow.stages) {
234:     const step = task.steps[stage.id];
235:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
236:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
237:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
238:     }
239:     const applies = condition(task, stage.condition, host);
240:     const decision = { stage: stage.id, skill: stage.skill };
241:     const stopAssessments = [...new Set([...(workflow.stop_conditions ?? []), ...stage.stop_conditions])].map(name => [name, condition(task, name, host)]);
242:     const stop = stopAssessments.find(([, value]) => value === true);
243:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop[0]}` };
244:     const unknownStop = stopAssessments.find(([, value]) => value === undefined);
245:     if (unknownStop) return { ...decision, action: 'evidence_insufficient', reason: `stop_condition_unknown:${unknownStop[0]}` };
246:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
247:     // Completed effects stay protected even when applicability changes. A new receipt
248:     // is not a reconciliation of the previous attempt's potentially different effects.
249:     const wasCompleted = ['completed', 'reused'].includes(step.status);
250:     const effectful = step.effect_state === 'known' || writes(stage, host)
251:       || host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files');
252:     if (stage.type === 'skill' && wasCompleted) {
253:       const denied = permission(stage.skill, stage, task, host);
254:       if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
255:       if (!stepEvidence(task, stage, host) && effectful) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
256:     }
257:     if (!applies) {
258:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
259:       // Applicability must not erase a completed operation or its known effects.
260:       if (['completed', 'reused'].includes(step.status)) { completed.add(stage.id); continue; }
261:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
262:       completed.add(stage.id); continue;
263:     }
264:     if (stage.type === 'gate') {
265:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
266:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
267:       for (const child of children) {
268:         const denied = permission(child.skill, child, task, host);
269:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
270:       }
271:       // Always re-evaluate gates against host grants, never reuse persisted approval.
272:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
273:       completed.add(stage.id); continue;
274:     }
275:     const denied = permission(stage.skill, stage, task, host);
276:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
277:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
278:       completed.add(stage.id); continue;
279:     }
280:     const failure = step.status === 'validation_failed';
281:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
282:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
283:     if (potentiallyEffectful(stage, host)) {
284:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
285:         .find(r => !requirement(task, r, host));
286:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
287:     }
288:     const candidate = host.reuse?.[stage.id];
289:     if (candidate) {
290:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate;
291:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
292:     }
293:     if ((writes(stage, host) || step.effect_state === 'known' || host.requests[stage.id].capabilities.some(c => c !== 'read_files')) && ['completed', 'reused'].includes(step.status)) {
294:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
295:     }
296:     if (host.verificationDeferral?.active === true) {
297:       const request = host.requests[stage.id];
298:       if (!host.verificationDeferral.source) {
299:         return { ...decision, action: 'evidence_insufficient', reason: 'verification_deferral_source_missing' };
300:       }
301:       if (request.capabilities.includes('run_shell_commands') && typeof request.verification !== 'boolean') {
302:         return { ...decision, action: 'evidence_insufficient', reason: 'command_verification_purpose_unknown' };
303:       }
304:       if (request.verification === true) {
305:         return { ...decision, action: 'evidence_insufficient', reason: 'verification_deferred',
306:           verification_status: 'verification_deferred', source: host.verificationDeferral.source,
307:           pending: host.verificationDeferral.pending ?? [], release_authorized: false };
308:       }
309:     }
310:     const unresolved = unresolvedFailures(task, host).find(failed => {
311:       const repair = host.failureRepairs?.get(digest(failed));
312:       return !repair?.source || repair.stages?.[stage.id] !== digest(host.requests[stage.id]);
313:     });
314:     if (unresolved) return { ...decision, action: evidenceValidity(unresolved, host).status === 'unknown' ? 'evidence_insufficient' : 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: unresolved.id };
315:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
316:   }
317:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
318:   const obligations = [
319:     ...task.acceptance.map(id => ({ claim: `acceptance:${id}` })),
320:     ...([...completed].some(id => {
321:       const stage = workflow.stages.find(s => s.id === id);
322:       return task.steps[id].status !== 'skipped'
323:         && ['feature-implementation', 'safe-fix-implementation', 'safe-test-implementation'].includes(stage.skill);
324:     }) ? [{ claim: 'behavior-validation', kind: 'test' }] : []),
325:     ...(host.deliveryRequirements ?? []),
326:     ...(host.risks ?? []).flatMap(r => {
327:       const rules = host.registry.coordination?.risk_requirements?.[r];
328:       return rules ? [...rules.before_write, ...rules.before_delivery] : [{ claim: `unclassified-risk:${r}` }];
329:     }),
330:   ];
331:   const failure = unresolvedFailures(task, host)[0];
332:   if (failure) return { action: evidenceValidity(failure, host).status === 'unknown' ? 'evidence_insufficient' : 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: failure.id };
333:   const missing = obligations.filter(r => !requirement(task, r, host));
334:   if (host.verificationDeferral?.active === true) {
335:     return { action: 'evidence_insufficient', reason: 'verification_deferred',
336:       verification_status: 'verification_deferred',
337:       source: host.verificationDeferral.source ?? null,
338:       pending: host.verificationDeferral.pending ?? [], missing,
339:       unresolved: [...task.unresolved], release_authorized: false };
340:   }
341:   if (task.unresolved.length || missing.length) return { action: 'evidence_insufficient', reason: 'delivery_not_proven', missing };
342:   return { action: 'complete', reason: 'applicable_stages_and_acceptance_proven', release_authorized: false };
343: }
344: 
345: function event(task, stage, status, reason) {
346:   task.current_stage = stage;
347:   task.history.push({ sequence: task.history.length + 1, stage, status, reason });
348: }
349: 
350: export function advance(task, host) {
351:   const action = nextAction(task, host);
352:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
353:     const step = task.steps[action.stage];
354:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
355:     step.reason = action.reason;
356:     if (['execute', 'reuse'].includes(action.action)) step.request_binding = digest(host.requests[action.stage]);
357:     if (action.action === 'execute') {
358:       step.attempts++;
359:       step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'uncertain' : 'none';
360:     }
361:     if (action.action === 'skip') {
362:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
363:       step.condition_binding = digest(host.conditions[stage.condition]);
364:     }
365:     if (action.action === 'reuse') step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'known' : 'none';
