373: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
374:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
375:   const step = task.steps[stageId];
376:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
377:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
378:   const denied = permission(stage.skill, stage, task, host);
379:   assert(!denied, denied);
380:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
381:   else {
382:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
383:     assert(stepEvidence(provisional, stage, host, step.attempts), 'Completion requires valid, scoped current-attempt evidence and independent review');
384:     step.evidence_ids = [...evidenceIds]; step.status = 'completed'; step.effect_state = step.effect_state === 'none' ? 'none' : 'known';
385:   }
386:   event(task, stageId, step.status, failureReason || 'observed_completion');
387: }
