392: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
393:   assert(reason && source, 'Reopen requires a sourced reason');
394:   const workflow = definition(task, host.registry, host.inventory);
395:   assert(task.steps[stageId], 'Unknown stage');
396:   const affected = new Set([stageId]);
