398:   while (changed) { changed = false; for (const stage of workflow.stages) {
399:     if (!affected.has(stage.id) && stage.prerequisites.some(id => affected.has(id))) { affected.add(stage.id); changed = true; }
400:   } }
401:   for (const id of affected) {
402:     const stage = workflow.stages.find(s => s.id === id);
403:     if (['running', 'interrupted'].includes(task.steps[id].status)
404:         || task.steps[id].effect_state === 'uncertain'
405:         || ((writes(stage, host) || task.steps[id].effect_state === 'known' || host.requests?.[id]?.capabilities?.some(c => c !== 'read_files')) && ['completed', 'reused', 'validation_failed'].includes(task.steps[id].status))) {
406:       assert(safeToRetry && host.reconciled?.has(reconciliationBinding(task, id, host)), 'Unknown side effects must be reconciled before retry');
407:     }
408:   }
409:   for (const id of affected) {
410:     const previous = task.steps[id].request_binding;
411:     task.steps[id].status = 'pending'; task.steps[id].effect_state = 'reconciled';
412:     delete task.steps[id].request_binding;
413:     event(task, id, 'pending', `${reason} (${source})`);
414:     if (previous) task.history.at(-1).previous_request_binding = previous;
415:   }
